<?php
namespace qqworld_collector\module\cloud_storage; use qqworld_collector\module\cloudStorage3; class github extends cloudStorage3 { var $email; var $repository_name; public function init() { $this->custom_upload_dir = $this->options->cloud_storage_github_custom_upload_dir; $this->protocol = $this->options->cloud_storage_github_protocol; $this->host = $this->options->cloud_storage_github_host; $this->folder = $this->options->cloud_storage_github_folder; $this->username = trim($this->options->cloud_storage_github_username); $this->email = $this->options->cloud_storage_github_email; $this->repository_name = trim($this->options->cloud_storage_github_repository_name); $this->token = $this->options->cloud_storage_github_token; $this->sync_delete = $this->options->cloud_storage_github_sync_delete; $this->silent_scanning = $this->options->cloud_storage_github_silent_scanning; $this->delete_attachment_after_synced = $this->options->cloud_storage_joinmode_enabled ? 0 : $this->options->cloud_storage_github_delete_attachment_after_synced; } public function access_service() { if ($this->enabled && $this->is_current && !$this->accessed && $this->repository_name && $this->token) { $this->accessed = true; } } public function is_object_exist($destination_path) { $url = 'https://raw.githubusercontent.com/' . $this->username . '/' . $this->repository_name . '/master/' . $destination_path; $response = wp_remote_head($url); $response_code = wp_remote_retrieve_response_code($response); return in_array($response_code, array(200,201,204)); } public function upload($destination_path, $source_path) { if (!file_exists($source_path) || !filesize($source_path)) return false; set_time_limit($this->options->qc_stress_timeout); $external_link = apply_filters( 'qqworld-collector-cloud-storage-github-upload', '', $destination_path, $source_path, $this ); if ($external_link) return $external_link; return false; } public function delete_object($object) { $blob = 'https://github.com/'.$this->username.'/'.$this->repository_name.'/blob/master/' . $destination_path; $html = file_get_contents($blob); $preg = preg_match('js-permalink-shortcut".*?\/blob\/([^\/]*?)\//i', $html, $match); if ($preg) { $sha = $match[1]; $args = array( 'method' => 'DELETE', 'sslverify' => false, 'headers' => array( 'authorization' => 'token ' . $this->token ), 'body' => '{"owner":"'.$this->username.'","repo":"'.$this->repository_name.'","path":"'.$destination_path.'","message":"delete picture via PicX(https://github.com/XPoet/picx)","sha":"'.$sha .'"}' ); $url = 'https://api.github.com/repos/'.$this->username.'/'.$this->repository_name.'/contents/' . $destination_path; $response = wp_remote_request($url, $args); } } public function add_form_fields() { require QQWORLD_COLLECTOR_DIR . 'pages' . DIRECTORY_SEPARATOR . 'cloudStorage3.php'; } public function add_could_storage_form($guid) { $this->access_service(); require QQWORLD_COLLECTOR_DIR . 'pages' . DIRECTORY_SEPARATOR . 'cloudStorage-'.$this->guid.'.php'; } } ?>